-- Plantilla de Ingemedic para cambio de equipo
INSERT INTO plantillas_acta (nombre, descripcion, bloques, accion, tipo, es_estandar, uso_general, activo)
SELECT 'Acta de cambio de equipo Ingemedic', 'Cambio de equipos médicos domiciliarios: el que se retira y el que se entrega. Se usa al cambiar un equipo con los clientes que no tienen formato propio.', $bloques$[{"tipo": "encabezado", "logos": [{"url": "https://olxkbdomwvdrcjhwppec.supabase.co/storage/v1/object/public/logos/logo-ingemedic.png", "alto": 50}], "ancho_logo": 28, "centro": [{"texto": "ACTA GENERAL DE EQUIPOS MEDICOS DOMICILIARIOS O SUMINISTRO OXIGENO DOMICILIARIO", "estilo": "titulo"}]}, {"tipo": "titulo", "texto": "CAMBIO DE EQUIPOS"}, {"tipo": "campos", "columnas": 3, "campos": [{"etiqueta": "CIUDAD", "valor": "{{ciudad}}"}, {"etiqueta": "FECHA", "valor": "{{fecha}}"}, {"etiqueta": "HORA", "valor": "{{hora}}"}]}, {"tipo": "tabla", "fuente": "retirados", "agrupar": "tipo", "titulo": "EQUIPOS QUE SE RETIRAN"}, {"tipo": "tabla", "fuente": "equipos", "agrupar": "tipo", "titulo": "EQUIPOS QUE SE ENTREGAN"}, {"tipo": "campos", "columnas": 3, "campos": [{"etiqueta": "MOTIVO DEL CAMBIO:", "valor": "{{motivo_cambio}}", "span": 3}, {"etiqueta": "QUIEN ENTREGA:", "valor": "{{entrega_nombre}}", "span": 2}, {"etiqueta": "FIRMA:", "firma": "entrega"}, {"etiqueta": "QUIEN RECIBE:", "valor": "{{recibe_nombre}}", "span": 2}, {"etiqueta": "FIRMA:", "firma": "recibe"}, {"etiqueta": "DIRECCION:", "valor": "{{paciente_direccion}}", "span": 2}, {"etiqueta": "TELEFONO", "valor": "{{recibe_telefono}}"}, {"etiqueta": "NOMBRE DEL PACIENTE:", "valor": "{{paciente_nombre}}", "span": 3}, {"etiqueta": "OBSERVACIONES: ( Especifique en este campo las observaciones que tenga acerca del estado del equipo en el momento de la cambio)", "valor": "{{observaciones}}", "span": 3, "arriba": true}]}, {"tipo": "texto", "tamano": 11, "texto": "Por medio de la presente acta se hace constar el cambio de los equipos biomedicos y/o suministros de oxigeno domiciliario descritos, entregados en calidad de prestamo. Los equipos que se retiran quedan bajo la custodia de INGEMEDIC DE COLOMBIA S.A.S; la custodia y buen uso de los equipos entregados son responsabilidad del paciente o familiar a partir de la fecha de este cambio."}]$bloques$::jsonb,
  'cambio', 'entrega', true, false, true
WHERE NOT EXISTS (SELECT 1 FROM plantillas_acta WHERE nombre = 'Acta de cambio de equipo Ingemedic');

-- Verificación: debe salir "cambio / true"
SELECT nombre, accion, es_estandar FROM plantillas_acta WHERE accion = 'cambio';
